    PPlant("bean","Фасоль","Овощные","Бобовые","Солнце","Умеренный","Лёгкая плодородная","Антракноз, бактериоз","Тля, фасолевая зерновка"),
    PPlant("tomato","Томат","Овощные","Паслёновые","Солнце","Умеренный","Плодородная","Фитофтороз, кладоспориоз","Белокрылка, тля"),
    PPlant("cucumber","Огурец","Овощные","Тыквенные","Солнце/полутень","Частый","Влажная плодородная","Мучнистая роса","Паутинный клещ, тля"),
    PPlant("apple","Яблоня","Плодово-ягодные","Розовые","Солнце","Умеренный","Суглинистая","Парша, плодовая гниль","Яблонная плодожорка, тля"),
    PPlant("strawberry","Клубника","Плодово-ягодные","Розовые","Солнце","Умеренный","Слабокислая","Серая гниль","Земляничный клещ, долгоносик"),
