@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun ProductionApp(db:AppDb) {
    val context=LocalContext.current; val scope=rememberCoroutineScope(); var screen by remember{mutableStateOf("home")}; var drawer by remember{mutableStateOf(false)}; var fileMode by remember{mutableStateOf("")}; val drawerState=rememberDrawerState(DrawerValue.Closed)
    LaunchedEffect(drawer){if(drawer)drawerState.open() else drawerState.close()}
    val exportLauncher=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/json")){uri->if(uri!=null)scope.launch{if(fileMode=="backup")exportBackup(context,db,uri)else exportQuiz(context,uri)};fileMode=""}
    val restoreLauncher=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null)scope.launch{restoreBackup(context,db,uri)}}
    fun nav(s:String){screen=s;drawer=false}
    ModalNavigationDrawer(drawerState=drawerState,drawerContent={ModalDrawerSheet{Text("🌿 AgroGarden",style=MaterialTheme.typography.headlineSmall,modifier=Modifier.padding(20.dp));Item("⌂","Главная",screen=="home"){nav("home")};HorizontalDivider();Text("🌱 Энциклопедия",modifier=Modifier.padding(16.dp));Item("🌿","Растения",screen=="plants"){nav("plants")};Item("♧","Семейства",screen=="families"){nav("families")};Item("🦠","Болезни",screen=="diseases"){nav("diseases")};Item("🐞","Вредители",screen=="pests"){nav("pests")};HorizontalDivider();Text("🚜 Хозяйство",modifier=Modifier.padding(16.dp));listOf("crops" to "🌾 Посевы","seeds" to "🌱 Семена","fertilizers" to "🧪 Удобрения","irrigation" to "💧 Полив","tasks" to "🔔 Напоминания","sales" to "💰 Продажи","harvest" to "🧺 Урожай","expenses" to "📉 Расходы","treatments" to "🛡️ Обработки","calendar" to "📅 Календарь","warehouse" to "📦 Склад","profit" to "📊 Прибыль","notes" to "📝 Блокнот","favorites" to "❤️ Избранное").forEach{(id,label)->Item("",label,screen==id){nav(id)}};HorizontalDivider();Text("💾 Данные",modifier=Modifier.padding(16.dp));Item("","Экспорт / резервная копия",false){fileMode="backup";exportLauncher.launch("agrogarden-backup.json")};Item("","Восстановить из копии",false){restoreLauncher.launch(arrayOf("application/json","text/*"))};Item("","Викторина",false){fileMode="quiz";exportLauncher.launch("agrogarden-quiz.json")}}}){Scaffold(topBar={TopAppBar(title={Text(title(screen))},navigationIcon={IconButton({drawer=true}){Text("☰")}})}){p->Box(Modifier.fillMaxSize().padding(p)){when(screen){"home"->Home(db,::nav);"plants"->Plants(db,"Все растения");"families"->Families();"diseases"->Knowledge("Болезни",catalog.flatMap{p->p.diseases.split(", ").map{it to p.name}}.distinct());"pests"->Knowledge("Вредители",catalog.flatMap{p->p.pests.split(", ").map{it to p.name}}.distinct());"crops"->Crops(db);"seeds"->Seeds(db);"fertilizers"->Fertilizers(db);"irrigation"->Irrigation(db);"tasks"->Tasks(db);"sales"->Sales(db);"harvest"->Harvest(db);"expenses"->Expenses(db);"treatments"->Treatments(db);"calendar"->Calendar(db);"warehouse"->Warehouse(db);"profit"->Profit(db);"notes"->Notes(db);"favorites"->Favorites(db)}}}}}
}
@Composable private fun Item(icon:String,label:String,selected:Boolean,onClick:()->Unit)=NavigationDrawerItem(label={Text(label)},selected=selected,onClick=onClick,icon={if(icon.isNotBlank())Text(icon)},modifier=Modifier.padding(NavigationDrawerItemDefaults.ItemPadding))
private fun title(s:String)=mapOf("home" to "AgroGarden","plants" to "Растения","families" to "Семейства","diseases" to "Болезни","pests" to "Вредители","crops" to "Посевы","seeds" to "Семена","fertilizers" to "Удобрения","irrigation" to "Полив","tasks" to "Напоминания","sales" to "Продажи","harvest" to "Урожай","expenses" to "Расходы","treatments" to "Обработки","calendar" to "Календарь","warehouse" to "Склад","profit" to "Прибыль","notes" to "Блокнот","favorites" to "Избранное")[s]?:"AgroGarden"

@Composable private fun Home(db:AppDb,nav:(String)->Unit){val f by db.fertilizers().all().collectAsState(emptyList());val s by db.seeds().all().collectAsState(emptyList());val t by db.tasks().all().collectAsState(emptyList());val sales by db.sales().all().collectAsState(emptyList());val ex by db.expenses().all().collectAsState(emptyList());val revenue=sales.sumOf{it.quantity*it.price};val costs=ex.sumOf{it.amount};LazyColumn(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("Полноценная панель хозяйства",style=MaterialTheme.typography.headlineSmall)};item{Info("⚠️ Минимальные остатки",if(f.any{it.quantity<=it.minStock})"Есть позиции ниже минимума" else "Все остатки в норме")};item{Info("🔔 Напоминания",t.count{!it.done}.toString())};item{Info("📊 Финансы","Выручка ${money(revenue)} • Расходы ${money(costs)} • Прибыль ${money(revenue-costs)}")};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.fillMaxWidth()){Button({nav("seeds")},Modifier.weight(1f)){Text("🌱 Семена")};Button({nav("fertilizers")},Modifier.weight(1f)){Text("🧪 Удобрения")}}};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.fillMaxWidth()){Button({nav("irrigation")},Modifier.weight(1f)){Text("💧 Полив")};Button({nav("tasks")},Modifier.weight(1f)){Text("🔔 Задачи")}}};item{Text("В складе семян: ${s.size} поз.")}}}
@Composable private fun Info(a:String,b:String)=Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Text(a,style=MaterialTheme.typography.titleMedium);Text(b)}}

@Composable private fun Plants(db:AppDb,filter:String){var q by remember{mutableStateOf("")};var selected by remember{mutableStateOf<PPlant?>(null)};if(selected!=null){LazyColumn(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{TextButton({selected=null}){Text("← Назад")};Text(selected!!.name,style=MaterialTheme.typography.headlineLarge)};item{Info("Категория",selected!!.category)};item{Info("Семейство",selected!!.family)};item{Info("Освещение",selected!!.light)};item{Info("Полив",selected!!.water)};item{Info("Почва",selected!!.soil)};item{Info("Болезни",selected!!.diseases)};item{Info("Вредители",selected!!.pests)}};return};val list=catalog.filter{(filter=="Все растения"||it.category==filter)&&(q.isBlank()||it.name.contains(q,true)||it.family.contains(q,true))};LazyColumn(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{OutlinedTextField(q,{q=it},Modifier.fillMaxWidth(),label={Text("Поиск")})};items(list){p->Card{ListItem(headlineContent={Text("🌿 ${p.name}")},supportingContent={Text("${p.category} • ${p.family}")},trailingContent={TextButton({selected=p}){Text("Открыть")}})}}}}
@Composable private fun Families(){val g=catalog.groupBy{it.family};LazyColumn(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){items(g.entries.toList()){(k,v)->Info(k,v.joinToString{it.name})}}}
@Composable private fun Knowledge(title:String,rows:List<Pair<String,String>>){LazyColumn(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text(title,style=MaterialTheme.typography.headlineSmall)};items(rows){(a,b)->ListItem(headlineContent={Text(a)},supportingContent={Text("Растение: $b")})}}}

