@Composable private fun <T> Form(title:String,form:@Composable ColumnScope.() -> Unit,list:List<T>,summary: @Composable (T) -> Unit,delete:(T)->Unit){LazyColumn(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text(title,style=MaterialTheme.typography.headlineSmall);Column(verticalArrangement=Arrangement.spacedBy(8.dp),content=form)};items(list){x->Card{Row(Modifier.fillMaxWidth().padding(8.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){Box(Modifier.weight(1f)){summary(x)};TextButton({delete(x)}){Text("🗑️")}}}}}}
@Composable private fun Field(v:String,set:(String)->Unit,label:String,modifier:Modifier=Modifier.fillMaxWidth())=OutlinedTextField(v,set,modifier,label={Text(label)})
@Composable private fun Add(onClick:()->Unit)=Button(onClick,Modifier.fillMaxWidth()){Text("➕ Добавить")}

private val fmt=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")
private fun key(prefix:String,vararg values:String)=(prefix+"_"+values.joinToString("|")).hashCode().toString()
private fun schedule(context:Context,title:String,date:String,time:String,repeat:Int,name:String){try{val target=LocalDateTime.parse("$date $time",fmt);val delay=Duration.between(LocalDateTime.now(),target).toMillis().coerceAtLeast(0);val data=Data.Builder().putString("title",title).putInt("repeatDays",repeat).putString("dateTime",target.toString()).putString("uniqueName",name).build();val req=OneTimeWorkRequestBuilder<ReminderWorker>().setInitialDelay(delay,TimeUnit.MILLISECONDS).setInputData(data).build();WorkManager.getInstance(context).enqueueUniqueWork(name,ExistingWorkPolicy.REPLACE,req)}catch(_:Exception){}}
private fun cancel(context:Context,name:String)=WorkManager.getInstance(context).cancelUniqueWork(name)
private fun money(v:Double)="%.2f".format(java.util.Locale.US,v)

private suspend fun exportBackup(context:Context,db:AppDb,uri:Uri)=withContext(Dispatchers.IO){val root=JSONObject().put("version",3).put("createdAt",System.currentTimeMillis());fun<T> arr(list:List<T>,map:(T)->JSONObject)=JSONArray().also{a->list.forEach{a.put(map(it))}};root.put("crops",arr(db.crops().all().first()){JSONObject().put("id",it.id).put("name",it.name).put("area",it.area).put("sowDate",it.sowDate).put("harvestDate",it.harvestDate).put("status",it.status).put("notes",it.notes)});root.put("seeds",arr(db.seeds().all().first()){JSONObject().put("id",it.id).put("name",it.name).put("quantity",it.quantity).put("unit",it.unit).put("batch",it.batch).put("expiry",it.expiry)});root.put("fertilizers",arr(db.fertilizers().all().first()){JSONObject().put("id",it.id).put("name",it.name).put("quantity",it.quantity).put("unit",it.unit).put("minStock",it.minStock)});root.put("irrigations",arr(db.irrigations().all().first()){JSONObject().put("id",it.id).put("crop",it.crop).put("date",it.date).put("time",it.time).put("volume",it.volume).put("repeatDays",it.repeatDays)});root.put("sales",arr(db.sales().all().first()){JSONObject().put("id",it.id).put("product",it.product).put("quantity",it.quantity).put("price",it.price).put("buyer",it.buyer).put("date",it.date)});root.put("harvests",arr(db.harvests().all().first()){JSONObject().put("id",it.id).put("crop",it.crop).put("quantity",it.quantity).put("date",it.date).put("quality",it.quality)});root.put("expenses",arr(db.expenses().all().first()){JSONObject().put("id",it.id).put("category",it.category).put("amount",it.amount).put("date",it.date).put("note",it.note)});root.put("treatments",arr(db.treatments().all().first()){JSONObject().put("id",it.id).put("crop",it.crop).put("issue",it.issue).put("product",it.product).put("date",it.date).put("note",it.note)});root.put("tasks",arr(db.tasks().all().first()){JSONObject().put("id",it.id).put("title",it.title).put("date",it.date).put("time",it.time).put("repeatDays",it.repeatDays).put("done",it.done)});root.put("notes",arr(db.notes().all().first()){JSONObject().put("id",it.id).put("title",it.title).put("text",it.text).put("createdAt",it.createdAt)});root.put("favorites",arr(db.favorites().all().first()){JSONObject().put("plantId",it.plantId).put("addedAt",it.addedAt)});context.contentResolver.openOutputStream(uri)?.use{it.write(root.toString(2).toByteArray(Charsets.UTF_8))}}
private suspend fun restoreBackup(context:Context,db:AppDb,uri:Uri)=withContext(Dispatchers.IO){val text=context.contentResolver.openInputStream(uri)?.bufferedReader()?.use{it.readText()}?:return@withContext;val root=JSONObject(text);db.clearAllTables();fun arr(n:String)=root.optJSONArray(n)?:JSONArray();var a=arr("crops");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.crops().add(Crop(x.optLong("id"),x.optString("name"),x.optDouble("area"),x.optString("sowDate"),x.optString("harvestDate"),x.optString("status"),x.optString("notes")))};a=arr("seeds");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.seeds().add(Seed(x.optLong("id"),x.optString("name"),x.optDouble("quantity"),x.optString("unit"),x.optString("batch"),x.optString("expiry")))};a=arr("fertilizers");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.fertilizers().add(Fertilizer(x.optLong("id"),x.optString("name"),x.optDouble("quantity"),x.optString("unit"),x.optDouble("minStock")))};a=arr("irrigations");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.irrigations().add(Irrigation(x.optLong("id"),x.optString("crop"),x.optString("date"),x.optString("time"),x.optDouble("volume"),x.optInt("repeatDays",1)))};a=arr("sales");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.sales().add(Sale(x.optLong("id"),x.optString("product"),x.optDouble("quantity"),x.optDouble("price"),x.optString("buyer"),x.optString("date")))};a=arr("harvests");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.harvests().add(Harvest(x.optLong("id"),x.optString("crop"),x.optDouble("quantity"),x.optString("date"),x.optString("quality")))};a=arr("expenses");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.expenses().add(Expense(x.optLong("id"),x.optString("category"),x.optDouble("amount"),x.optString("date"),x.optString("note")))};a=arr("treatments");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.treatments().add(Treatment(x.optLong("id"),x.optString("crop"),x.optString("issue"),x.optString("product"),x.optString("date"),x.optString("note")))};a=arr("tasks");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.tasks().add(Task(x.optLong("id"),x.optString("title"),x.optString("date"),x.optString("time"),x.optInt("repeatDays",1),x.optBoolean("done")))};a=arr("notes");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.notes().add(Note(x.optLong("id"),x.optString("title"),x.optString("text"),x.optLong("createdAt")))};a=arr("favorites");for(i in 0 until a.length()){val x=a.getJSONObject(i);db.favorites().add(FavoritePlant(x.optString("plantId"),x.optLong("addedAt")))}}
private fun exportQuiz(context:Context,uri:Uri){context.contentResolver.openOutputStream(uri)?.use{it.write("AgroGarden — викторина\n\n1. Что показывает minStock?\nA) Минимальный остаток удобрения\nB) Период полива\n\n2. Для чего нужен WorkManager?\nA) Для фоновых задач и напоминаний\nB) Для хранения фото\n".toByteArray(Charsets.UTF_8))}
